CREATE TABLE profiles (id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE, full_name TEXT, display_name TEXT, phone TEXT, bio TEXT, avatar_url TEXT, avatar_key TEXT, role TEXT NOT NULL DEFAULT 'student', metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, code TEXT UNIQUE, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE organization_members (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','admin','teacher','student')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(organization_id,user_id));
CREATE INDEX organization_member_user ON organization_members(user_id,organization_id);
CREATE TABLE classrooms (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, term TEXT, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX classroom_org ON classrooms(organization_id);
CREATE TABLE classroom_members (id TEXT PRIMARY KEY, classroom_id TEXT NOT NULL REFERENCES classrooms(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('teacher','student')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(classroom_id,user_id));
CREATE INDEX classroom_member_user ON classroom_members(user_id,classroom_id);
CREATE TABLE programs (id TEXT PRIMARY KEY, classroom_id TEXT NOT NULL REFERENCES classrooms(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published')), metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX program_classroom ON programs(classroom_id);
CREATE TABLE org_invites (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, email TEXT NOT NULL CHECK(email=lower(trim(email))), role TEXT NOT NULL CHECK(role IN ('admin','teacher','student')), invited_by TEXT NOT NULL REFERENCES profiles(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(organization_id,email));
CREATE TABLE classroom_invites (id TEXT PRIMARY KEY, classroom_id TEXT NOT NULL REFERENCES classrooms(id) ON DELETE CASCADE, email TEXT NOT NULL CHECK(email=lower(trim(email))), invited_by TEXT NOT NULL REFERENCES profiles(id), expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(classroom_id,email));
CREATE TABLE algorithm_submissions (id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, content TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','rejected')), feedback TEXT, reviewer_id TEXT REFERENCES profiles(id), reviewed_at TEXT, version INTEGER NOT NULL DEFAULT 1, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(program_id,student_id));
CREATE TABLE code_submissions (id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, code TEXT NOT NULL DEFAULT '', language TEXT, output TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','rejected')), feedback TEXT, reviewer_id TEXT REFERENCES profiles(id), reviewed_at TEXT, version INTEGER NOT NULL DEFAULT 1, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(program_id,student_id));
CREATE INDEX algorithm_review ON algorithm_submissions(program_id,status);
CREATE INDEX code_review ON code_submissions(program_id,status);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, organization_id TEXT, action TEXT NOT NULL, resource_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE api_usage (actor_id TEXT NOT NULL, feature TEXT NOT NULL, window_start INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(actor_id,feature,window_start));
-- Transient assertions force a batch rollback if a conditional creation loses authorization.
CREATE TABLE mutation_guards (id TEXT PRIMARY KEY, allowed INTEGER NOT NULL CHECK(allowed=1));
